const CONFIRM_WORDS =
  /\b(confirmo|confirmar|dale mandalo|manda|enviar|listo cerralo|ok confirmo)\b/i;

function stripMarkdownFence(text) {
  return String(text || '')
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
}

function parseAgentJson(raw) {
