function validateAgentOutput(agent, ctx) {
  const reply = String(agent.reply || '').trim();
  if (!reply) return { ok: false, error: 'empty_reply' };

  const blocked = [
    /agriencuestas\.mendoza\.gov\.ar/i,
    /identif_olivos/i,
    /Feno26-/i,
    /qued[oó] validado oficialmente/i,
    /enviado a central/i,
    /xform real/i,
  ];
